const http = this.helpers.httpRequest;

const SUPABASE_URL = 'https://zavabpchdvssvdnwtuyu.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InphdmFicGNoZHZzc3Zkbnd0dXl1Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODQzNDA4NDgsImV4cCI6MjA5OTkxNjg0OH0.bGIex-jior3Q48OAwXRmuwJbt6SZ_MQMiyiieY4WDm4';
const supabaseHeaders = { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY };

async function getSubscribers() {
  const url = SUPABASE_URL + '/rest/v1/alert_subscribers?product=eq.secop&active=eq.true&select=phone,plan,config';
  try {
    const data = await http({ method: 'GET', url, headers: supabaseHeaders });
    return Array.isArray(data) ? data : [];
  } catch (e) {
    return [];
  }
}

async function sendMsg(phone, text) {
  return http({
    method: 'POST',
    url: 'http://148.230.90.171:8096/message/sendText/wasapea-7c7a2c6c',
    headers: { 'apikey': 'wasapea-evo-key-2026', 'Content-Type': 'application/json' },
    body: { number: phone, text: text }
  });
}

// 1. Fetch SECOP contracts (last 48h)
const base = 'https://www.datos.gov.co/resource/jbjy-vk9h.json';
const now = new Date();
const since = new Date(now.getTime() - 48 * 60 * 60 * 1000).toISOString().split('T')[0];
const params = '$select=nombre_entidad,descripcion_del_proceso,valor_del_contrato,fecha_de_firma,departamento,ciudad,modalidad_de_contratacion,tipo_de_contrato,urlproceso,id_contrato&$where=fecha_de_firma%20%3E=%20%27' + since + '%27&$order=fecha_de_firma%20DESC&$limit=20';
const data = await http({ method: 'GET', url: base + '?' + params });

if (!Array.isArray(data) || data.length === 0) {
  return { sent: 0, message: 'No contracts in last 48h' };
}

// 2. Fetch subscribers
const subscribers = await getSubscribers();
if (subscribers.length === 0) {
  return { sent: 0, message: 'No active subscribers' };
}

// 3. For each subscriber, filter contracts by keywords and send
const results = [];
const DEFAULT_KEYWORDS = ['eléctric', 'electric', 'energ', 'solar', 'panel', 'transformador', 'red', 'subestación', 'iluminación', 'led', 'cable', 'generador'];

for (const sub of subscribers) {
  const keywords = (sub.config && sub.config.keywords && sub.config.keywords.length > 0)
    ? sub.config.keywords
    : DEFAULT_KEYWORDS;

  const matches = data.filter(item => {
    const text = (item.descripcion_del_proceso || '') + ' ' + (item.nombre_entidad || '');
    return keywords.some(kw => text.toLowerCase().includes(kw.toLowerCase()));
  });

  if (matches.length === 0) continue;

  for (const item of matches) {
    const desc = (item.descripcion_del_proceso || 'Sin descripción').substring(0, 120);
    const valorFmt = item.valor_del_contrato
      ? '$' + Number(item.valor_del_contrato).toLocaleString('es-CO')
      : 'No especificado';
    const fecha = item.fecha_de_firma
      ? new Date(item.fecha_de_firma).toLocaleDateString('es-CO')
      : 'Sin fecha';
    const urlLink = (item.urlproceso && item.urlproceso.url)
      ? item.urlproceso.url
      : 'https://community.secop.gov.co/';

    const text = '📋 *Licitación SECOP*\n\n' +
      '🏛️ *' + item.nombre_entidad + '*\n' +
      '📍 ' + (item.departamento || '') + ', ' + (item.ciudad || '') + '\n' +
      '📝 ' + desc + '...\n' +
      '💰 ' + valorFmt + '\n' +
      '📅 ' + fecha + '\n' +
      '🏷️ ' + (item.modalidad_de_contratacion || '') + '\n\n' +
      '🔗 ' + urlLink + '\n\n' +
      '⚡ *SECOP Alertas*';

    try {
      await sendMsg(sub.phone, text);
      results.push({ phone: sub.phone, contract: item.id_contrato, status: 'sent' });
    } catch (e) {
      results.push({ phone: sub.phone, status: 'error' });
    }
  }
}

return { sent: results.filter(r => r.status === 'sent').length, contracts: data.length, subscribers: subscribers.length };
